<script setup lang="ts">
import { computed, ref, watch } from 'vue';

/** 一行解析结果，带「与现有树相比怎么样」的标记 */
export type 解析行 = {
  键: string;
  变量名: string;
  值: string;
  预设id: string;
  条目id: string;
  条目名: string;
  标记: '新增变量' | '新增来源' | '值不同' | '已一致';
  /** 已一致时，现有树里那条的值，供对照 */
  现有值?: string;
};

const props = defineProps<{
  展开: boolean;
  解析中: boolean;
  预设名: string;
  行: 解析行[];
  /** 出错信息，非空时只显示错误 */
  错误: string;
}>();

const emit = defineEmits<{
  应用: [选中的行: 解析行[], 覆盖: boolean];
  关闭: [];
}>();

const 勾选 = ref<Set<string>>(new Set());

/** 需要用户注意的三种标记；「已一致」不需要勾 */
const 有差异 = computed(() => props.行.filter(r => r.标记 !== '已一致'));
const 统计 = computed(() => ({
  总数: props.行.length,
  新增变量: props.行.filter(r => r.标记 === '新增变量').length,
  新增来源: props.行.filter(r => r.标记 === '新增来源').length,
  值不同: props.行.filter(r => r.标记 === '值不同').length,
}));

// 每次出结果默认只勾有差异的 —— 「已一致」的勾上也没意义，反而让列表看着吵
watch(
  () => props.行,
  value => {
    勾选.value = new Set(value.filter(r => r.标记 !== '已一致').map(r => r.键));
  },
  { immediate: true },
);

function 切换(键: string) {
  const 下一个 = new Set(勾选.value);
  下一个.has(键) ? 下一个.delete(键) : 下一个.add(键);
  勾选.value = 下一个;
}

const 标记样式: Record<解析行['标记'], string> = {
  新增变量: 'bg-accent-soft/50 text-accent',
  新增来源: 'bg-warn/20 text-warn',
  值不同: 'bg-danger/15 text-danger',
  已一致: 'bg-surface2 text-muted',
};

const 标记说明: Record<解析行['标记'], string> = {
  新增变量: '正则扫描完全没发现这个变量',
  新增来源: '变量已知，但这条条目没被认成它的来源',
  值不同: '这条来源已知，但 AI 读出的值和现有不同',
  已一致: '现有树里已经有完全一样的一条，无需处理',
};

function 采纳勾选(覆盖: boolean) {
  emit(
    '应用',
    有差异.value.filter(r => 勾选.value.has(r.键)),
    覆盖,
  );
}

function 全选() {
  勾选.value = 勾选.value.size ? new Set() : new Set(有差异.value.map(r => r.键));
}
</script>

<template>
  <div v-if="展开" class="fixed inset-0 z-50 flex items-center justify-center p-4" @click.self="emit('关闭')">
    <!-- 遮罩 -->
    <div class="absolute inset-0 bg-black/50" />

    <div class="relative glass-strong rounded-xl w-full max-w-2xl max-h-[85vh] flex flex-col overflow-hidden">
      <div class="px-3 py-2 shrink-0 border-b border-line flex items-center gap-2 text-xs">
        <i class="fa-solid fa-wand-sparkles text-accent" />
        <span class="font-medium">AI 解析变量树</span>
        <span class="text-muted truncate max-w-64">{{ 预设名 }}</span>
        <button class="ml-auto text-muted hover:text-danger" @click="emit('关闭')">
          <i class="fa-solid fa-xmark" />
        </button>
      </div>

      <p v-if="错误" class="p-3 text-xs text-danger leading-relaxed">{{ 错误 }}</p>

      <div v-else-if="解析中" class="p-4 text-xs text-accent flex items-center gap-2">
        <i class="fa-solid fa-spinner fa-spin" />正在通读预设…这一步会按条目数量分批调用 AI，请稍候
      </div>

      <template v-else>
        <div class="px-3 py-2 shrink-0 border-b border-line/60 flex items-center gap-2 flex-wrap text-[11px]">
          <span class="text-muted">共 {{ 统计.总数 }} 条</span>
          <span v-if="统计.新增变量" class="text-accent">新增变量 {{ 统计.新增变量 }}</span>
          <span v-if="统计.新增来源" class="text-warn">新增来源 {{ 统计.新增来源 }}</span>
          <span v-if="统计.值不同" class="text-danger">值不同 {{ 统计.值不同 }}</span>
          <button class="ml-auto text-muted hover:text-accent" @click="全选">
            {{ 勾选.size ? '全不选' : '全选' }}
          </button>
        </div>

        <div class="flex-1 min-h-0 overflow-y-auto">
          <div v-if="行.length === 0" class="p-4 text-xs text-muted">
            AI 没有在这个预设里找到任何变量。可能是这个预设本来就不含变量，或者内容太抽象。
          </div>

          <div
            v-for="r in 行"
            :key="r.键"
            class="px-3 py-1.5 border-b border-line/40 flex items-start gap-2 text-xs transition-colors"
            :class="r.标记 === '已一致' ? 'opacity-55' : 'hover:bg-surface2/50'"
          >
            <input
              type="checkbox"
              class="shrink-0 mt-0.5"
              :disabled="r.标记 === '已一致'"
              :checked="勾选.has(r.键)"
              @change="切换(r.键)"
            />
            <div class="flex-1 min-w-0">
              <div class="flex items-center gap-1.5">
                <span class="font-medium truncate">{{ r.变量名 }}</span>
                <span
                  class="shrink-0 px-1 rounded text-[10px]"
                  :class="标记样式[r.标记]"
                  :title="标记说明[r.标记]"
                >
                  {{ r.标记 }}
                </span>
              </div>
              <div class="text-[10px] text-muted truncate">
                值：{{ r.值 || '（空）' }}
                <span v-if="r.标记 === '值不同'" class="text-danger">｜现有：{{ r.现有值 || '（空）' }}</span>
              </div>
              <div class="text-[10px] text-muted truncate">来源：{{ r.条目名 }}</div>
            </div>
          </div>
        </div>

        <div class="px-3 py-2 shrink-0 border-t border-line flex flex-wrap items-center gap-2">
          <span class="text-[10px] text-muted flex-1 min-w-40">
            「查漏补缺」只补现有的树里没有的；「覆盖」会丢掉这个预设的正则扫描结果、完全以 AI 为准
          </span>
          <button
            class="px-2.5 py-1 rounded-md border border-line hover:border-accent text-xs disabled:opacity-40"
            :disabled="勾选.size === 0"
            title="把勾选的都并进现有树，已有的保留不动"
            @click="采纳勾选(false)"
          >
            查漏补缺（{{ 勾选.size }}）
          </button>
          <button
            class="px-2.5 py-1 rounded-md border border-danger text-danger text-xs disabled:opacity-40"
            :disabled="勾选.size === 0"
            title="以 AI 结果替换该预设的正则扫描结果"
            @click="采纳勾选(true)"
          >
            <i class="fa-solid fa-triangle-exclamation mr-1" />覆盖整棵树
          </button>
        </div>
      </template>
    </div>
  </div>
</template>
