import type {
  DanglingVar,
  ImportedPreset,
  PresetPrompt,
  VarConflict,
  VarConsoleSource,
  VarDef,
  VarRef,
} from '../types.ts';

/** 变量宏: 支持 set/get 与 setglobal/getglobal 四种 */
const DEF_PATTERN = /\{\{(setvar|setglobalvar)::([^}]*?)\}\}/g;
const REF_PATTERN = /\{\{(getvar|getglobalvar)::([^}]*?)\}\}/g;
const COMMENT_PATTERN = /\{\{\/\/\s*(.*?)\}\}/g;

/* ============ 变量树节点 id ============ */

/**
 * 声明节点 id。变量名做 URI 编码 —— `splitNameValue` 已保证名字里不含 `::`，
 * 但变量名可能含 `{`、`}` 等字符，编码一次可以彻底免疫分隔符冲突。
 */
export function 声明节点id(变量名: string): string {
  return `decl::${encodeURIComponent(变量名)}`;
}

/** 把 `名字::值` 拆开, 值里允许出现冒号 */
function splitNameValue(body: string): { name: string; value: string } {
  const index = body.indexOf('::');
  if (index === -1) return { name: body.trim(), value: '' };
  return { name: body.slice(0, index).trim(), value: body.slice(index + 2) };
}

/**
 * 扫描所有导入预设, 找出其中的变量定义。
 *
 * 识别规则:
 * - 硬条件: 条目内容含 {{setvar::}} 或 {{setglobalvar::}}
 * - 忽略列表: 用户在 UI 里手动排除的条目 id
 *
 * 为什么不做"名字含变量/控制台"的加权自动判定:
 * 加权判定会引入不可预测的行为, 用户看到识别结果不对却不知道为什么。
 * 改为把识别结果显式列出 + 提供手动排除, 规则简单且可控。
 */
export function scanVariableDefs(presets: ImportedPreset[], ignoredPromptIds: string[]): VarConsoleSource[] {
  const ignored = new Set(ignoredPromptIds);
  const sources: VarConsoleSource[] = [];

  for (const preset of presets) {
    const allPrompts = [...(preset.raw.prompts ?? []), ...(preset.raw.prompts_unused ?? [])];
    for (const prompt of allPrompts) {
      if (ignored.has(prompt.id)) continue;
      const content = prompt.content ?? '';
      if (!/\{\{(setvar|setglobalvar)::/.test(content)) continue;

      // 单次遍历, 同时记录注释分组与变量定义的出现顺序
      const events: { index: number; kind: 'comment' | 'def'; text: string }[] = [];
      for (const match of content.matchAll(COMMENT_PATTERN)) {
        events.push({ index: match.index, kind: 'comment', text: match[1].trim() });
      }
      for (const match of content.matchAll(DEF_PATTERN)) {
        events.push({ index: match.index, kind: 'def', text: match[2] });
      }
      events.sort((a, b) => a.index - b.index);

      const defs: VarDef[] = [];
      let seq = 0;
      let currentGroup: string | null = null;

      for (const event of events) {
        if (event.kind === 'comment') {
          currentGroup = event.text || null;
          continue;
        }
        const { name, value } = splitNameValue(event.text);
        if (!name) continue;
        defs.push({
          name,
          value,
          presetId: preset.id,
          presetName: preset.name,
          promptId: prompt.id,
          promptName: prompt.name,
          seq: seq++,
          group: currentGroup,
        });
      }

      if (defs.length > 0) {
        sources.push({
          presetId: preset.id,
          presetName: preset.name,
          promptId: prompt.id,
          promptName: prompt.name,
          defs,
          content,
        });
      }
    }
  }

  return sources;
}

/** 扫描条目的变量引用, 按变量名聚合引用次数与来源条目 id */
export function scanVariableRefs(prompts: PresetPrompt[]): VarRef[] {
  const map = new Map<string, VarRef>();
  for (const prompt of prompts) {
    const content = prompt.content ?? '';
    for (const match of content.matchAll(REF_PATTERN)) {
      const name = match[2].trim();
      if (!name) continue;
      const ref = map.get(name) ?? { name, count: 0, uids: [] };
      ref.count += 1;
      if (!ref.uids.includes(prompt.id)) ref.uids.push(prompt.id);
      map.set(name, ref);
    }
  }
  return [...map.values()];
}

/* ============ 合并 ============ */

export type MergedVariables = {
  conflicts: VarConflict[];
  dangling: DanglingVar[];
  /** 定义了但没有任何条目引用的变量名 */
  unused: string[];
  /** 去重、按首次出现顺序排列、且值已按裁决结果解析好的定义 */
  ordered: VarDef[];
};

/**
 * 合并各来源的变量定义。
 *
 * 裁决顺序: 用户手动值 (agreedValue) > 首个来源的值。
 *
 * 为什么 agreedValue 与 defs 分开存:
 * 源预设快照可能被重新拉取, 直接把裁决结果写进 defs 会让用户的选择被静默冲掉。
 * 分开存放后, 重新拉取只换 defs, 裁决还在。
 * ordered 里给出的已是解析后的值, 供直接渲染。
 */
export function mergeVariables(
  sources: VarConsoleSource[],
  refs: VarRef[],
  agreedValue: Record<string, string>,
): MergedVariables {
  const firstSeen = new Map<string, VarDef>();
  const byName = new Map<string, VarDef[]>();

  for (const source of sources) {
    for (const def of source.defs) {
      if (!firstSeen.has(def.name)) firstSeen.set(def.name, def);
      const list = byName.get(def.name) ?? [];
      list.push(def);
      byName.set(def.name, list);
    }
  }

  const conflicts: VarConflict[] = [];
  for (const [name, defs] of byName) {
    const distinct = new Set(defs.map(d => d.value));
    if (distinct.size > 1 && !(name in agreedValue)) {
      conflicts.push({
        name,
        candidates: defs.map(d => ({ presetId: d.presetId, presetName: d.presetName, value: d.value })),
      });
    }
  }

  // 悬空引用: 被引用但既无定义也无用户补值
  const dangling: DanglingVar[] = refs
    .filter(ref => !firstSeen.has(ref.name) && !(ref.name in agreedValue))
    .map(ref => ({ name: ref.name, refCount: ref.count }))
    .sort((a, b) => b.refCount - a.refCount);

  // 有序定义: 先排已有定义(按首次出现顺序), 再追加用户补值的悬空变量
  const ordered: VarDef[] = [...firstSeen.values()].map(def => ({
    ...def,
    value: agreedValue[def.name] ?? def.value,
  }));
  for (const [name, value] of Object.entries(agreedValue)) {
    if (firstSeen.has(name)) continue;
    ordered.push({
      name,
      value,
      presetId: '',
      presetName: '(手动补齐)',
      promptId: '',
      promptName: '',
      seq: Number.MAX_SAFE_INTEGER,
      group: null,
    });
  }

  const referenced = new Set(refs.map(r => r.name));
  const unused = ordered.filter(d => !referenced.has(d.name)).map(d => d.name);

  return { conflicts, dangling, unused, ordered };
}

/** 按用户手动排除的变量名过滤合并结果，只影响渲染，不改动原始数据 */
export function 排除变量(merged: MergedVariables, excluded: string[]): MergedVariables {
  if (excluded.length === 0) return merged;
  const 集 = new Set(excluded);
  return {
    ...merged,
    ordered: merged.ordered.filter(d => !集.has(d.name)),
    unused: merged.unused.filter(n => !集.has(n)),
    dangling: merged.dangling.filter(d => !集.has(d.name)),
    conflicts: merged.conflicts.filter(c => !集.has(c.name)),
  };
}

/* ============ 渲染 ============ */

/**
 * 渲染「声明条目」：只声明变量名，值留空。
 *
 * 形如 {{setvar::核心语言:: }}
 *
 * 为什么拆成「声明」与「赋值」两条：
 * 变量值往往很长（一整段风格描述），直接塞进声明条目会让它变成一大坨难以阅读和维护的东西；
 * 而且同一批变量可能想换一套值。声明固定、赋值独立，换值就只动赋值条目。
 */
export function renderDeclaration(merged: MergedVariables): string {
  return merged.ordered.map(d => `{{setvar::${d.name}:: }}`).join('\n');
}

/**
 * 渲染某个来源的「赋值条目」：这一来源下的变量及其值。
 *
 * 保留原控制台条目的名字（例如「📜剧作家变量控制台」），
 * 这样一眼能看出这组值是哪个预设带来的，也方便日后对照。
 */
export function renderSourceValues(
  source: VarConsoleSource,
  merged: MergedVariables,
  excluded: string[],
  /**
   * 被单独取消勾选的「来源 × 变量」值行，键由 值行id() 生成。
   * 【可选】：不传 = 不做这一层过滤，既有调用方与单测行为不变。
   */
  跳过的值行?: Set<string>,
): string {
  const 排除集 = new Set(excluded);
  const 值表 = new Map(merged.ordered.map(d => [d.name, d.value]));

  const 行: string[] = [];
  let 上一组: string | null | undefined;
  for (const def of source.defs) {
    if (排除集.has(def.name)) continue;
    if (跳过的值行?.has(值行id(source.presetId, source.promptId, def.name))) continue;
    // 同一分组的变量连续出现时，分组注释只写一次
    if (def.group !== 上一组) {
      if (def.group) 行.push(`{{// ${def.group}}}`);
      上一组 = def.group;
    }
    行.push(`{{setvar::${def.name}::${值表.get(def.name) ?? def.value}}}`);
  }
  return 行.join('\n');
}

/* ============ 变量树 ============ */

/**
 * 节点是否已勾选（= 是否写入目标预设）。
 *
 * 缺省视为勾选：`injected` 里没有这个 key = 用户没动过 = 用默认全选。
 * 用户显式取消后写的是 `false`。所以只判断 `!== false` 一种情况即可覆盖两者。
 */
export function 节点已勾选(injected: Record<string, boolean>, nodeId: string): boolean {
  return injected[nodeId] !== false;
}

/** 值行 id：某个来源条目给某个变量的那一条赋值 */
export function 值行id(presetId: string, promptId: string, 变量名: string): string {
  return `value::${presetId}::${promptId}::${encodeURIComponent(变量名)}`;
}

/**
 * 取一段文本的第一个非空行。
 *
 * 【必须跳过空行】实测数据里 `{{setvar::X::` 后面常常直接跟换行，例如：
 *   {{setvar::性爱前置::
 *   [性爱前置：温柔性爱]
 *   - 以深化情感连接…
 *   }}
 * 老老实实取「第一行」会拿到空字符串，节点就显示成空的了。
 */
export function 首个非空行(文本: string): string {
  for (const 行 of 文本.split('\n')) {
    const 去空 = 行.trim();
    if (去空) return 去空;
  }
  return '';
}

export type 变量状态 = 'conflict' | 'dangling' | 'unused' | 'ok';

export type 树行 = {
  id: string;
  类型: 'decl' | 'value';
  /** 变量名。value 行表示「这是哪个变量的赋值」 */
  变量名: string;
  /** 显示的值：decl 行是裁决后的值，value 行是该来源自己给出的值 */
  值: string;
  /** 仅声明行 */
  状态?: 变量状态;
  候选?: { 预设名: string; 值: string }[];
  /** 仅值行 */
  预设名?: string;
  条目名?: string;
  /**
   * 仅值行：该条目正文的第一个非空行，作树上的预览用。
   *
   * 为什么不拿 `值`（setvar 的值）当预览：实测的预设里，
   * `{{setvar::创作要求3::内在罗盘}}` 这类宏的值只是一个短标签，
   * 同一变量的三个变体（常规 / 淡人 / 高干）值**完全一样**，
   * 靠它根本区分不出该选哪条。真正有区分度的是条目正文。
   */
  预览?: string;
};

/** 一个「只声明变量、不给任何值」的来源条目 */
export type 声明来源 = {
  presetId: string;
  promptId: string;
  预设名: string;
  条目名: string;
  /** 它声明了多少个变量 */
  数量: number;
};

/**
 * 判断一个来源是不是「纯声明条目」。
 *
 * 实测的预设里 `📜获取变量` 就是这种：它把几十个变量全部声明一遍空值
 * （`{{setvar::核心语言:: }}{{setvar::双语对话:: }}…`），真正的值由别的条目给。
 * 判据是「有定义、且每一条定义的值都是空」。
 */
export function 是纯声明来源(源: VarConsoleSource): boolean {
  return 源.defs.length > 0 && 源.defs.every(d => !d.value.trim());
}

export type 变量图 = {
  /**
   * 按纵向顺序排列的行。
   *
   * 【不变量】一个声明行后面紧跟它的**全部**值行，然后才是下一个声明行。
   * 布局直接按数组下标取 y 坐标，连线因此**在数学上不可能交叉** ——
   * 这是「线不要太多交叉」的实现方式：不靠避让算法，靠把数据排成不会交叉的顺序。
   */
  行: 树行[];
  连线: { from: string; to: string }[];
  /**
   * 纯声明来源，单独拎出来。
   *
   * 不把它们画成值行的理由：它们给每个变量都定义了一遍，照常画的话
   * **每一根树杈上都会挂同一个条目**，树被撑得又长又重复，
   * 而这些空值提供不了任何区分信息。改成在顶栏显示成一个可点的入口。
   */
  声明来源: 声明来源[];
};

/**
 * 构建变量树。
 *
 * 形状：左列一个变量一条声明节点，右边连着它的各个赋值来源（值行）。
 * 一个变量有几个来源定义它，就长几根树杈 —— 对应「一个声明串联好几个条目」。
 *
 * 传进来的 `合并结果` 必须是【未按勾选过滤】的原始合并结果：用户在树上取消勾选后
 * 还得能看见并点回来，删掉节点就没法复原了。勾选状态由 UI 直接读 `injected`。
 */
export function buildVarGraph(来源: VarConsoleSource[], 合并结果: MergedVariables): 变量图 {
  const 冲突表 = new Map(合并结果.conflicts.map(c => [c.name, c]));
  const 未用集 = new Set(合并结果.unused);

  // 纯声明条目（全是空值）不进值行，单独收集起来给顶栏用
  const 值来源: VarConsoleSource[] = [];
  const 声明来源: 声明来源[] = [];
  for (const 源 of 来源) {
    if (是纯声明来源(源)) {
      声明来源.push({
        presetId: 源.presetId,
        promptId: 源.promptId,
        预设名: 源.presetName,
        条目名: 源.promptName,
        数量: new Set(源.defs.map(d => d.name)).size,
      });
    } else {
      值来源.push(源);
    }
  }

  // 变量名 → 定义了它的来源列表（保持来源出现顺序，顺序稳定才不会每次重排都跳）
  const 定义表 = new Map<string, VarConsoleSource[]>();
  for (const 源 of 值来源) {
    // 去重：同一来源里同名变量可能出现多次，多根线叠在一起看不出区别
    for (const 名 of new Set(源.defs.map(d => d.name))) {
      const 列表 = 定义表.get(名) ?? [];
      列表.push(源);
      定义表.set(名, 列表);
    }
  }

  const 行: 树行[] = [];
  const 连线: { from: string; to: string }[] = [];

  /** 压入一个声明行 + 它的全部值行（连着的顺序不能拆开，否则连线会乱） */
  function 压入变量(变量名: string, 值: string, 状态: 变量状态, 候选?: 树行['候选']) {
    const 声明id = 声明节点id(变量名);
    行.push({ id: 声明id, 类型: 'decl', 变量名, 值, 状态, 候选 });

    for (const 源 of 定义表.get(变量名) ?? []) {
      // 显示来源自己给出的值，而不是裁决后的值：
      // 冲突时用户正是要靠这个对比才知道该选谁
      const 该源的值 = 源.defs.find(d => d.name === 变量名)?.value ?? '';
      const id = 值行id(源.presetId, 源.promptId, 变量名);
      行.push({
        id,
        类型: 'value',
        变量名,
        值: 该源的值,
        预设名: 源.presetName,
        条目名: 源.promptName,
        预览: 首个非空行(源.content ?? '') || '（空条目）',
      });
      连线.push({ from: 声明id, to: id });
    }
  }

  for (const d of 合并结果.ordered) {
    const 冲突 = 冲突表.get(d.name);
    压入变量(
      d.name,
      d.value,
      (冲突 ? 'conflict' : 未用集.has(d.name) ? 'unused' : 'ok') as 变量状态,
      冲突?.candidates.map(c => ({ 预设名: c.presetName, 值: c.value })),
    );
  }

  // 被引用但没有定义、也没补值的变量也要进树 —— 否则用户在界面上根本看不到它，无从补值
  for (const d of 合并结果.dangling) {
    压入变量(d.name, '', 'dangling');
  }

  return { 行, 连线, 声明来源 };
}


/* ============ 并入 AI 解析结果 ============ */

/** 一条「某来源条目在给某变量赋值」的配对 */
export type AI配对 = { 预设id: string; 条目id: string; 变量名: string; 值: string };

/**
 * 把 AI 解析出来的配对并进扫描结果。
 *
 * 设计上刻意【不动 buildVarGraph】—— 它只管「拿到一份 VarConsoleSource 列表就画树」。
 * AI 结果在这里被翻译成同样的形状，下游完全无感。
 * 这样「AI 补全」与「正则扫描」就成了同一条流水线上的两个来源，而不是两套并行逻辑。
 *
 * @param 接管预设 被 AI 结果完全接管的预设 id：这些预设的扫描结果整个丢掉，改由 AI 重建
 */
export function 并入AI配对(
  来源: VarConsoleSource[],
  配对: AI配对[],
  接管预设: string[],
  导入表: ImportedPreset[],
): VarConsoleSource[] {
  if (配对.length === 0 && 接管预设.length === 0) return 来源;

  const 接管集 = new Set(接管预设);
  // 浅拷贝外层数组，绝不改调用方传进来的对象
  const 结果: VarConsoleSource[] = 来源.filter(s => !接管集.has(s.presetId));

  /** 键：(预设, 条目) —— 与 值行id 的口径一致 */
  const 键 = (预设id: string, 条目id: string) => `${预设id}::${条目id}`;

  // 先把现存的来源按 (预设, 条目) 索引好，AI 配对能挂上去就直接挂
  const 索引 = new Map<string, number>();
  结果.forEach((s, i) => 索引.set(键(s.presetId, s.promptId), i));

  for (const 对 of 配对) {
    if (!对.变量名) continue;
    const k = 键(对.预设id, 对.条目id);
    const 已有下标 = 索引.get(k);

    if (已有下标 === undefined) {
      // 这条来源在扫描结果里没有（AI 才发现它也在赋值），按需造一个
      const 预设 = 导入表.find(i => i.id === 对.预设id);
      const 条目 = 预设
        ? [...(预设.raw.prompts ?? []), ...(预设.raw.prompts_unused ?? [])].find(p => p.id === 对.条目id)
        : undefined;
      if (!预设 || !条目) continue;

      const 新源: VarConsoleSource = {
        presetId: 对.预设id,
        presetName: 预设.name,
        promptId: 对.条目id,
        promptName: 条目.name,
        defs: [],
        content: 条目.content ?? '',
      };
      // 复制一份再挂，别把 defs 数组和调用方共享
      新源.defs = [构造定义(新源, 对)];
      索引.set(k, 结果.length);
      结果.push(新源);
      continue;
    }

    const 源 = 结果[已有下标];
    // 同一个变量在同一来源里已经有一条定义就不重复加，否则树会长出重复的值行
    if (源.defs.some(d => d.name === 对.变量名)) continue;
    源.defs = [...源.defs, 构造定义(源, 对)];
  }

  return 结果;
}

function 构造定义(源: VarConsoleSource, 对: AI配对): VarDef {
  return {
    name: 对.变量名,
    value: 对.值,
    presetId: 源.presetId,
    presetName: 源.presetName,
    promptId: 源.promptId,
    promptName: 源.promptName,
    seq: 源.defs.length,
    group: null,
  };
}
