import { computed, ref } from 'vue';
import { 对齐改写, 取术语参照, 取注入内容 } from './ai.ts';
import { useWorkspaceStore } from './store.ts';
import type { AiResult } from '../types.ts';

/**
 * 「条目比对」的队列逻辑，桌面版与手机版共用。
 *
 * 抽出来的理由：这段包含写入 / 放弃 / 重新生成三条路径和队列下标的增减，
 * 在两份 App.vue 里各抄一遍的话，以后修一处必然漏另一处 ——
 * 而两边共用 core/，放在这里天然只有一份。
 *
 * 只负责「比对什么、怎么处理」，不碰任何布局状态（页签、子分段、编辑对象），
 * 那些是各端外壳自己的事。
 */
export function 用比对队列() {
  const store = useWorkspaceStore();
  const 槽位 = computed(() => store.slot);

  /** 待逐条确认的 AiResult id */
  const 队列 = ref<string[]>([]);
  const 下标 = ref(0);

  const 当前 = computed<AiResult | null>(
    () => 槽位.value.aiResults.find(r => r.id === 队列.value[下标.value]) ?? null,
  );

  /** 建队列。单条传 [id] 即可 */
  function 开始(ids: string[]) {
    if (ids.length === 0) return;
    队列.value = [...ids];
    下标.value = 0;
  }

  /** 摘掉当前项；下标不动，后面的自动补上来 */
  function 出队() {
    队列.value = 队列.value.filter((_, i) => i !== 下标.value);
    if (队列.value.length === 0) {
      下标.value = 0;
      return;
    }
    下标.value = Math.min(下标.value, 队列.value.length - 1);
  }

  /** 写入：把 AI 版本写进目标条目，这条随之从「待确认」里消失 */
  function 写入() {
    const r = 当前.value;
    if (!r) return;
    store.应用AI结果(r.id);
    出队();
    toastr.success(`已写入「${r.name}」`, '预设缝合助手');
  }

  /** 放弃：不用 AI 版本，保留原条目，并把这条结果移除 */
  function 放弃() {
    const r = 当前.value;
    if (!r) return;
    store.移除AI结果(r.id);
    出队();
  }

  function 关闭() {
    队列.value = [];
  }

  /* ============ 重新生成 ============ */

  const 重做展开 = ref(false);
  const 重做中 = ref(false);

  function 打开重做() {
    if (!当前.value) return;
    重做展开.value = true;
  }

  /**
   * 按修改意见让 AI 重做这一条。
   *
   * 以【当前这版 AI 结果】为底而不是回到原条目：用户说「再克制一点」时，
   * 意思是「在现在这版基础上再克制」，不是「忘掉重来」。
   * 结果仍写回暂存区，不直接进目标 —— 要落到目标上还得再点一次「写入」。
   */
  async function 执行重做(意见: string) {
    const 结果 = 当前.value;
    if (!结果) return;

    重做中.value = true;
    try {
      const 新内容 = await 对齐改写(
        结果.content,
        取术语参照(store.skeleton),
        取注入内容(槽位.value.prompts, store.workspace.ai.injectionExcluded),
        意见,
        store.workspace.ai.prompts.rewrite,
      );
      store.更新AI结果(结果.id, { content: 新内容 });
      重做展开.value = false;
      toastr.success('已按你的意见重做，看新版本', '预设缝合助手');
    } catch (error) {
      console.error(error);
      toastr.error(`重做失败：${error instanceof Error ? error.message : String(error)}`, '预设缝合助手');
    } finally {
      重做中.value = false;
    }
  }

  return { 队列, 当前, 开始, 写入, 放弃, 关闭, 重做展开, 重做中, 打开重做, 执行重做 };
}
