<script setup lang="ts">
import { computed, nextTick, ref } from 'vue';
import { 解析变量树, type AI变量配对 } from '../core/ai.ts';
import { deepClone } from '../core/clone.ts';
import { 元素窗口 } from '../core/panel.ts';
import SplitHandle from './SplitHandle.vue';
import { useWorkspaceStore } from '../core/store.ts';
import {
  buildVarGraph,
  mergeVariables,
  renderDeclaration,
  renderSourceValues,
  scanVariableDefs,
  scanVariableRefs,
  并入AI配对,
  节点已勾选,
  声明节点id,
  排除变量,
  值行id,
} from '../core/variables.ts';
import AiTreeDialog, { type 解析行 } from './AiTreeDialog.vue';
import VariableTree from './VariableTree.vue';
import {
  VARIABLE_CONSOLE_NAME,
  VARIABLE_CONSOLE_UID,
  type ImportedPreset,
  type TargetPrompt,
  type 编辑对象,
} from '../types.ts';

const props = defineProps<{
  /** 左栏当前选中的预设 id。「AI 解析」解析的就是它 */
  预设id: string | null;
}>();

const emit = defineEmits<{
  编辑条目: [
    对象: 编辑对象 | null,
    动作: { 变量名: string; 值: string } | null,
  ];
}>();

const store = useWorkspaceStore();
/**
 * 点击顶部统计即可筛选。
 * 接到变量树上表现为「非该状态的声明卡片变淡」，而不是把它们从图里删掉 ——
 * 删节点会让连线断掉、布局跳动，反而不容易看清结构。
 */
const 筛选 = ref<null | 'conflict' | 'dangling' | 'unused'>(null);

/** 上半区高度占比，拖中间那根线可调 */
const 上半占比 = ref(55);

/**
 * 分隔线拖动。
 *
 * 样式【必须】用 computed 返回对象，不能在模板里写 `:style="{ flex: `${上半占比} 1 0%` }"`。
 * 模板字符串里的 ref 一旦没被正确解包，生成的就是 "[object Object] 1 0%" 这种非法 CSS，
 * 整条声明会被浏览器丢弃，元素退回内容高度 —— 上半区撑满、分隔线掉到最底部。
 * 这个坑排查了很久，别再踩。
 */
const 上半样式 = computed(() => ({ flex: `${上半占比.value} 1 0%` }));
const 下半样式 = computed(() => ({ flex: `${100 - 上半占比.value} 1 0%` }));

/** 效果预览里左侧目录选中的条目 */
const 目录选中 = ref(0);
/** 效果预览右侧内容容器，用于点目录时定位 */
const 预览容器 = ref<HTMLElement | null>(null);

/**
 * 左侧目录点某条 → 右侧滚到对应位置。
 * 用预览容器自己的 ownerDocument 查询：组件执行在酒馆主页面作用域，
 * 裸 document 是找不到面板 iframe 里的元素的。
 */
async function 跳到条目(下标: number) {
  目录选中.value = 下标;
  await nextTick();
  const 视图 = 元素窗口(预览容器.value);
  视图.document.querySelector(`[data-预览="${下标}"]`)?.scrollIntoView({ block: 'start', behavior: 'smooth' });
}



const 槽位 = computed(() => store.slot);
const 参与条目 = computed(() => 槽位.value.prompts);

/** 纯正则扫描的结果。「现有树长什么样」以它为准，作为 AI 解析的对比基准 */
const 扫描来源 = computed(() =>
  scanVariableDefs(store.workspace.imports, 槽位.value.variables.ignoredConsolePromptIds),
);

/**
 * 实际喂给变量树的来源 = 正则扫描 + AI 解析确认过的配对。
 *
 * AI 结果在这里就被翻译成和扫描完全一样的形状，所以 buildVarGraph 一行都不用改 ——
 * 「AI 补全」与「正则扫描」是同一条流水线上的两个来源，而不是两套并行逻辑。
 */
const 来源 = computed(() =>
  并入AI配对(
    扫描来源.value,
    槽位.value.variables.ai配对,
    槽位.value.variables.ai接管,
    store.workspace.imports,
  ),
);
const 引用 = computed(() => scanVariableRefs(参与条目.value));
/** 未按勾选过滤的原始合并结果 —— 树上要能看见并点回来被取消勾选的变量 */
const 合并结果 = computed(() => mergeVariables(来源.value, 引用.value, 槽位.value.variables.agreedValue));

/** 变量树节点的注入开关表 */
const 注入 = computed(() => 槽位.value.variables.injected);

/**
 * 未勾选的变量名。由 `injected` 派生，而不是单独存一份名单 ——
 * 两处状态必然不同步，这正是 v1 的 `excluded` 字段被移除的原因。
 * 派生结果直接喂给既有的 `排除变量` / `renderSourceValues`，语义与 v1 完全一致。
 */
const 排除名单 = computed(() =>
  合并结果.value.ordered
    .filter(d => !节点已勾选(注入.value, 声明节点id(d.name)))
    .map(d => d.name),
);

const 有效合并 = computed(() => 排除变量(合并结果.value, 排除名单.value));

/**
 * 被单独取消勾选的「来源 × 变量」值行。
 * 与声明层的 `排除名单` 是两层过滤：声明层管「这个变量要不要」，
 * 这里管「某个来源给这个变量的那条赋值要不要」。
 */
const 跳过的值行 = computed(() => {
  const 集 = new Set<string>();
  for (const 源 of 来源.value) {
    for (const 名 of new Set(源.defs.map(d => d.name))) {
      const id = 值行id(源.presetId, 源.promptId, 名);
      if (!节点已勾选(注入.value, id)) 集.add(id);
    }
  }
  return 集;
});

/** 变量树 */
const 图 = computed(() => buildVarGraph(来源.value, 合并结果.value));

/** 纯声明条目（把变量声明一遍空值、不给值的那种），显示在顶栏右侧 */
const 声明来源 = computed(() => 图.value.声明来源);

/** 树上的统计（行序列里按类型数） */
const 树统计 = computed(() => ({
  变量数: 图.value.行.filter(n => n.类型 === 'decl').length,
  值数: 图.value.行.filter(n => n.类型 === 'value').length,
}));

/** 树上选中的节点 id */
const 选中树节点 = ref<string | null>(null);

/** 扫描设置（被识别为变量控制台的条目）是否展开 */
const 展开高级 = ref(false);

/* ============ AI 解析 ============ */

const 展开解析 = ref(false);
const 解析中 = ref(false);
const 解析预设 = ref('');
const 解析行 = ref<解析行[]>([]);
const 解析错误 = ref('');

/** 有哪些变量是现有树里已经知道的（用于判断 AI 找到的是「新变量」还是「新来源」） */
function 已知变量集(): Set<string> {
  const 集 = new Set<string>();
  for (const 源 of 扫描来源.value) for (const d of 源.defs) 集.add(d.name);
  for (const 对 of 槽位.value.variables.ai配对) 集.add(对.变量名);
  return 集;
}

async function 执行解析() {
  const id = props.预设id;
  if (!id) {
    toastr.warning('先在左栏选一个预设', '预设缝合助手');
    return;
  }
  const 预设 = store.workspace.imports.find(i => i.id === id);
  if (!预设) return;

  const 条目 = store.条目(预设);
  if (条目.length === 0) {
    toastr.warning('这个预设没有条目', '预设缝合助手');
    return;
  }

  解析预设.value = 预设.name;
  解析错误.value = '';
  解析行.value = [];
  解析中.value = true;
  展开解析.value = true;

  try {
    const 原始 = await 解析变量树(
      条目.map(t => ({ id: t.id, name: t.name, content: t.content ?? '' })),
    );
    解析行.value = 生成对比行(原始, 预设);
    if (解析行.value.length === 0) {
      toastr.info('AI 没有找到变量', '预设缝合助手');
    }
  } catch (error) {
    console.error(error);
    解析错误.value = `解析失败：${error instanceof Error ? error.message : String(error)}`;
  } finally {
    解析中.value = false;
  }
}

/** 把 AI 的产出与现有树逐条比对，标出差异 */
function 生成对比行(配对: AI变量配对[], 预设: ImportedPreset): 解析行[] {
  // (条目id, 变量名) → 扫描出来的现有值
  const 现有边 = new Map<string, string>();
  for (const 源 of 扫描来源.value) {
    for (const d of 源.defs) 现有边.set(`${源.promptId}::${d.name}`, d.value);
  }
  const 已知 = 已知变量集();
  const 条目名表 = new Map(store.条目(预设).map(t => [t.id, t.name]));

  const 序: Record<解析行['标记'], number> = { 新增变量: 0, 新增来源: 1, 值不同: 2, 已一致: 3 };

  return 配对
    .map(对 => {
      const 键 = `${对.条目id}::${对.变量名}`;
      const 有边 = 现有边.has(键);
      const 标记: 解析行['标记'] = 有边
        ? 现有边.get(键) === 对.值
          ? '已一致'
          : '值不同'
        : 已知.has(对.变量名)
          ? '新增来源'
          : '新增变量';

      return {
        键,
        变量名: 对.变量名,
        值: 对.值,
        预设id: 预设.id,
        条目id: 对.条目id,
        条目名: 条目名表.get(对.条目id) ?? '（未知条目）',
        标记,
        现有值: 有边 ? 现有边.get(键) : undefined,
      };
    })
    .sort((a, b) => 序[a.标记] - 序[b.标记] || a.变量名.localeCompare(b.变量名));
}

/** 撤销 AI 解析，退回纯正则扫描 */
function 撤销解析() {
  const 预设id = props.预设id;
  if (!预设id) return;
  if (!confirm('撤销后该预设回到纯正则扫描的结果，AI 找到的配对会全部丢弃。确定吗？')) return;
  store.清除AI解析(预设id);
  toastr.success('已撤销 AI 解析', '预设缝合助手');
}

function 应用解析(选中的行: 解析行[], 覆盖: boolean) {
  store.应用AI解析(
    props.预设id ?? '',
    选中的行.map(r => ({ 预设id: r.预设id, 条目id: r.条目id, 变量名: r.变量名, 值: r.值 })),
    覆盖,
  );
  展开解析.value = false;
  toastr.success(
    覆盖 ? `已用 AI 结果覆盖该预设的变量树（${选中的行.length} 条）` : `已补入 ${选中的行.length} 条`,
    '预设缝合助手',
  );
}

/** 声明条目内容：只声明变量名 */
const 声明内容 = computed(() => renderDeclaration(有效合并.value));

/** 各来源的赋值条目 */
const 值条目 = computed(() =>
  来源.value
    .map(源 => ({
      键: `${源.presetId}::${源.promptId}`,
      // 保留原控制台条目的名字，一眼看出这组值来自哪个预设
      名: 源.promptName,
      预设名: 源.presetName,
      内容: renderSourceValues(源, 有效合并.value, 排除名单.value, 跳过的值行.value),
    }))
    .filter(项 => 项.内容.trim().length > 0),
);

const 已有控制台 = computed(() => 槽位.value.prompts.some(t => t._uid === VARIABLE_CONSOLE_UID));

const 统计 = computed(() => ({
  总数: 有效合并.value.ordered.length,
  冲突: 合并结果.value.conflicts.length,
  悬空: 有效合并.value.dangling.length,
  未用: 有效合并.value.unused.length,
  已排除: 排除名单.value.length,
}));

function 点统计(键: 'conflict' | 'dangling' | 'unused') {
  筛选.value = 筛选.value === 键 ? null : 键;
}

/* ============ 操作 ============ */

function 裁决(名字: string, 值: string) {
  槽位.value.variables.agreedValue = { ...槽位.value.variables.agreedValue, [名字]: 值 };
  // 裁决过的变量自动勾选回来，否则用户会困惑「选了值却不生效」
  槽位.value.variables.injected = { ...槽位.value.variables.injected, [声明节点id(名字)]: true };
  store.save();
}

function 切换注入(nodeId: string) {
  store.切换注入(nodeId);
}

/**
 * 点树节点 → 右栏条目编辑器打开对应的真实条目。
 *
 * - 声明行：它本身不是一个真实条目（要「应用到目标」后才成为合并声明里的一行），
 *   所以打开目标栏里的那条声明条目，比什么都不做有用
 * - 值行：直接打开它所属的【源条目】。变量的值往往嵌在一大段提示词里
 *   （例如一整套创作要求），只显示「研究母题」四个字判断不了该不该采用，
 *   必须能看到完整正文
 * - 该变量有冲突时，额外带一个「采用这个值」的动作给编辑器做成浮条
 */
function 点树节点(id: string) {
  选中树节点.value = id;

  const 行 = 图.value.行.find(n => n.id === id);
  if (!行) {
    emit('编辑条目', null, null);
    return;
  }

  /*
   * 声明行本身不是一个真实存在的条目（它要去「应用到目标」之后才成为
   * 那条合并声明里的一行），所以这里打开的是目标栏里的声明条目。
   * 比什么都不做好：至少能看见它最终会变成什么。
   */
  if (行.类型 === 'decl') {
    const 已有声明条目 = 槽位.value.prompts.some(t => t._uid === VARIABLE_CONSOLE_UID);
    emit('编辑条目', 已有声明条目 ? { 类型: 'target', uid: VARIABLE_CONSOLE_UID } : null, null);
    return;
  }

  // 值行指向的是一个真实存在的源条目，直接编辑它
  const 源 = 来源.value.find(s => 值行id(s.presetId, s.promptId, 行.变量名) === id);
  if (!源) {
    emit('编辑条目', null, null);
    return;
  }

  const 有冲突 = 合并结果.value.conflicts.some(c => c.name === 行.变量名);
  emit(
    '编辑条目',
    { 类型: 'source', presetId: 源.presetId, promptId: 源.promptId },
    有冲突 ? { 变量名: 行.变量名, 值: 行.值 } : null,
  );
}

function 切换识别条目(条目标识: string) {
  const 列表 = 槽位.value.variables.ignoredConsolePromptIds;
  槽位.value.variables.ignoredConsolePromptIds = 列表.includes(条目标识)
    ? 列表.filter(i => i !== 条目标识)
    : [...列表, 条目标识];
  store.save();
}

/**
 * 写入目标：一条声明条目 + 每个来源一条赋值条目。
 * 声明条目锁定在首位（引用它的条目必须先取到变量值）。
 */
function 应用到目标() {
  const 声明: TargetPrompt = {
    id: 'var-console',
    name: VARIABLE_CONSOLE_NAME,
    enabled: true,
    role: 'system',
    content: 声明内容.value,
    position: { type: 'relative' },
    _uid: VARIABLE_CONSOLE_UID,
    _from: null,
    _origin: '',
    _mode: 'raw',
  };

  // 已存在的赋值条目先清掉，避免改名后残留
  const 值条目前缀 = 'var-values::';
  const 保留 = 槽位.value.prompts.filter(t => !t._uid.startsWith(值条目前缀) && t._uid !== VARIABLE_CONSOLE_UID);

  const 新值条目: TargetPrompt[] = 值条目.value.map(项 => ({
    id: `var-values-${项.键}`,
    name: 项.名,
    enabled: true,
    role: 'system',
    content: 项.内容,
    position: { type: 'relative' },
    _uid: `${值条目前缀}${项.键}`,
    _from: null,
    _origin: '',
    _mode: 'raw',
  }));

  槽位.value.prompts = [deepClone(声明), ...新值条目, ...保留];
  槽位.value.variables.consoleUid = VARIABLE_CONSOLE_UID;
  store.save();

  toastr.success(
    `已写入 1 条声明条目 + ${新值条目.length} 条赋值条目`,
    '预设缝合助手',
  );
  emit('选中条目', VARIABLE_CONSOLE_UID);
}
</script>

<template>
  <div class="flex flex-col flex-1 min-h-0">
    <!-- 统计条：点击即筛选 -->
    <div class="px-2.5 py-1.5 border-b border-line shrink-0 flex items-center gap-1.5 text-xs flex-wrap">
      <span
        class="px-1.5 py-0.5 rounded cursor-pointer transition-colors"
        :class="筛选 === null ? 'bg-accent text-accent-text' : 'bg-surface2 hover:bg-line'"
        title="显示全部"
        @click="筛选 = null"
      >
        变量 {{ 统计.总数 }}
      </span>
      <span
        v-if="统计.冲突"
        class="px-1.5 py-0.5 rounded cursor-pointer transition-colors text-warn"
        :class="筛选 === 'conflict' ? 'bg-warn text-accent-text' : 'bg-warn/15 hover:bg-warn/25'"
        title="点击只看初值有分歧的变量"
        @click="点统计('conflict')"
      >
        冲突 {{ 统计.冲突 }}
      </span>
      <span
        v-if="统计.悬空"
        class="px-1.5 py-0.5 rounded cursor-pointer transition-colors text-danger"
        :class="筛选 === 'dangling' ? 'bg-danger text-accent-text' : 'bg-danger/15 hover:bg-danger/25'"
        title="点击只看被引用但没有定义的变量"
        @click="点统计('dangling')"
      >
        悬空 {{ 统计.悬空 }}
      </span>
      <span
        v-if="统计.未用"
        class="px-1.5 py-0.5 rounded cursor-pointer transition-colors text-muted"
        :class="筛选 === 'unused' ? 'bg-line' : 'bg-surface2 hover:bg-line'"
        title="点击只看定义了但没有条目引用的变量"
        @click="点统计('unused')"
      >
        未用 {{ 统计.未用 }}
      </span>
      <span v-if="统计.已排除" class="text-muted">已排除 {{ 统计.已排除 }}</span>

      <!--
        纯声明条目（如预设里的「📜获取变量」）的入口。
        它们把每个变量都声明一遍空值，画进树里会让每根树杈都挂同一个条目，
        所以单独放这儿 —— 不占树的空间，又能随时点开查看。
      -->
      <span class="ml-auto flex items-center gap-1 shrink-0">
        <button
          v-for="s in 声明来源"
          :key="s.promptId"
          class="px-1.5 py-0.5 rounded border border-line hover:border-accent text-[11px] truncate max-w-52 transition-colors"
          :title="`纯声明条目：声明了 ${s.数量} 个变量但都不给值\n来自预设：${s.预设名}\n点击查看内容`"
          @click="emit('编辑条目', { 类型: 'source', presetId: s.presetId, promptId: s.promptId }, null)"
        >
          <i class="fa-solid fa-file-lines mr-1 opacity-70" />{{ s.条目名 }}
        </button>
        <span v-if="声明来源.length === 0" class="text-muted">{{ 来源.length }} 个控制台</span>
      </span>
    </div>

    <!-- 上半：变量树 -->
    <div class="min-h-0 flex flex-col" :style="上半样式">
      <div class="px-2.5 py-1.5 shrink-0 flex items-center gap-2 text-[11px] bg-surface2/45 border-b border-line/50">
        <span class="text-muted">变量树</span>
        <span class="text-muted">· {{ 树统计.变量数 }} 个变量 / {{ 树统计.值数 }} 条赋值</span>
        <button
          class="shrink-0 px-1.5 py-0.5 rounded border transition-colors whitespace-nowrap disabled:opacity-40"
          :class="
            槽位.variables.ai配对.length || 槽位.variables.ai接管.length
              ? 'border-accent text-accent'
              : 'border-line text-muted hover:border-accent hover:text-accent'
          "
          :disabled="!props.预设id || 解析中"
          :title="
            props.预设id
              ? '让 AI 通读这个预设，补出正则扫不到的变量来源'
              : '先在左栏点一个预设，再回来解析'
          "
          @click="执行解析"
        >
          <i class="fa-solid fa-wand-sparkles mr-0.5" />
          {{ 解析中 ? '解析中…' : 'AI 解析' }}
          <span v-if="槽位.variables.ai配对.length" class="ml-0.5">
            {{ 槽位.variables.ai配对.length }}
          </span>
        </button>
        <button
          v-if="来源.length"
          class="shrink-0 px-1.5 py-0.5 rounded border transition-colors whitespace-nowrap"
          :class="展开高级 ? 'border-accent text-accent' : 'border-line text-muted hover:border-line-strong'"
          title="扫描设置：查看、排除被识别为变量控制台的条目"
          @click="展开高级 = !展开高级"
        >
          <i class="fa-solid fa-gear mr-0.5" />高级设置
        </button>
      </div>

      <!-- 已接入 AI 解析时的状态条 + 一键退回正则扫描 -->
      <div
        v-if="槽位.variables.ai配对.length || 槽位.variables.ai接管.length"
        class="shrink-0 px-2.5 py-1 border-b border-line/50 bg-accent-soft/20 flex items-center gap-2 text-[10px]"
      >
        <i class="fa-solid fa-wand-sparkles text-accent shrink-0" />
        <span class="text-accent flex-1 truncate">
          AI 解析已生效：补入 {{ 槽位.variables.ai配对.length }} 条配对<template
            v-if="槽位.variables.ai接管.length"
          >
            ，{{ 槽位.variables.ai接管.length }} 个预设由 AI 完全接管</template
          >
        </span>
        <button
          class="shrink-0 text-muted hover:text-danger"
          title="撤销 AI 解析，退回纯正则扫描"
          @click="撤销解析"
        >
          撤销
        </button>
      </div>

      <!--
        扫描设置收起来不占地方。原来它是一条常驻的折叠栏，
        但绝大多数时候扫描都是对的，为此常驻一行不划算。
      -->
      <div v-if="展开高级 && 来源.length" class="shrink-0 border-b border-line/50 max-h-44 overflow-y-auto">
        <div class="px-2.5 py-1 text-[10px] text-muted">
          被识别为变量控制台的条目（{{ 来源.length }}）。若某条是扫描误判，点 ✕ 把它排除。
        </div>
        <div v-for="s in 来源" :key="s.promptId" class="flex items-center gap-2 px-2.5 py-0.5 text-[11px]">
          <span class="truncate flex-1">{{ s.presetName }} · {{ s.promptName }}</span>
          <span class="text-muted shrink-0">{{ s.defs.length }} 个变量</span>
          <button
            class="text-muted hover:text-danger shrink-0"
            title="排除该条目：它定义的变量不再进树"
            @click="切换识别条目(s.promptId)"
          >
            <i class="fa-solid fa-xmark" />
          </button>
        </div>
      </div>

      <VariableTree
        :图="图"
        :注入="注入"
        :选中id="选中树节点"
        :筛选="筛选"
        @选中="点树节点"
        @切换注入="切换注入"
        @裁决="裁决"
      />
    </div>
    <SplitHandle @拖动="比例 => (上半占比 = 比例)" />

    <!-- 下半：效果预览 -->
    <div class="min-h-0 flex flex-col" :style="下半样式">
      <div class="px-2.5 py-1.5 shrink-0 flex items-center gap-2 text-[11px] bg-surface2/45 border-b border-line/50">
        <span class="text-muted">效果预览</span>
        <span class="text-muted">· {{ 值条目.length + 1 }} 条条目</span>
        <button
          class="ml-auto px-2 py-0.5 rounded bg-accent text-accent-text font-medium disabled:opacity-40"
          :disabled="有效合并.ordered.length === 0"
          @click="应用到目标"
        >
          {{ 已有控制台 ? '更新目标' : '应用到目标' }}
        </button>
      </div>

      <div class="flex-1 min-h-0 flex gap-2 p-2">
        <!-- 左：条目目录 -->
        <div class="w-40 shrink-0 flex flex-col min-h-0 rounded-md border border-line overflow-hidden">
          <div class="px-2 py-1.5 shrink-0 text-[10px] text-muted bg-surface2/60 border-b border-line">条目目录</div>
          <div class="flex-1 min-h-0 overflow-y-auto">
            <button
              class="w-full text-left px-2 py-1 text-[11px] border-b border-line/40 transition-colors"
              :class="目录选中 === 0 ? 'bg-accent-soft/40 text-accent' : 'hover:bg-surface2/60'"
              title="声明条目：只放变量名，锁定首位"
              @click="跳到条目(0)"
            >
              <div class="flex items-center gap-1">
                <i class="fa-solid fa-lock text-warn text-[9px]" />
                <span class="truncate flex-1">{{ VARIABLE_CONSOLE_NAME }}</span>
              </div>
              <div class="text-[9px] text-muted pl-3.5">声明 · {{ 有效合并.ordered.length }} 个变量</div>
            </button>

            <button
              v-for="(项, i) in 值条目"
              :key="项.键"
              class="w-full text-left px-2 py-1 text-[11px] border-b border-line/40 transition-colors"
              :class="目录选中 === i + 1 ? 'bg-accent-soft/40 text-accent' : 'hover:bg-surface2/60'"
              :title="`赋值条目，来自 ${项.预设名}`"
              @click="跳到条目(i + 1)"
            >
              <div class="flex items-center gap-1">
                <i class="fa-solid fa-equals text-accent text-[9px]" />
                <span class="truncate flex-1">{{ 项.名 }}</span>
              </div>
              <div class="text-[9px] text-muted pl-3.5 truncate">来自 {{ 项.预设名 }}</div>
            </button>
          </div>
        </div>

        <!-- 右：条目内容 -->
        <div ref="预览容器" class="flex-1 min-w-0 min-h-0 overflow-y-auto space-y-2">
          <div class="rounded-md border border-warn/40 overflow-hidden" data-预览="0">
            <div class="px-2 py-1 bg-warn/10 text-[10px] flex items-center gap-1.5">
              <i class="fa-solid fa-lock text-warn" />
              <span class="truncate">{{ VARIABLE_CONSOLE_NAME }}</span>
              <span class="text-muted ml-auto">声明 · 锁定首位</span>
            </div>
            <pre class="p-2 bg-surface2/50 text-[11px] leading-relaxed whitespace-pre-wrap font-mono">{{ 声明内容 || '（没有变量）' }}</pre>
          </div>

          <div
            v-for="(项, i) in 值条目"
            :key="项.键"
            class="rounded-md border border-line overflow-hidden"
            :data-预览="i + 1"
          >
            <div class="px-2 py-1 bg-surface2 text-[10px] flex items-center gap-1.5">
              <i class="fa-solid fa-equals text-accent" />
              <span class="truncate">{{ 项.名 }}</span>
              <span class="text-muted ml-auto truncate">赋值 · 来自 {{ 项.预设名 }}</span>
            </div>
            <pre class="p-2 bg-surface2/50 text-[11px] leading-relaxed whitespace-pre-wrap font-mono">{{ 项.内容 }}</pre>
          </div>

          <p class="text-[10px] text-muted leading-relaxed">
            声明条目只放变量名（空值），实际值放在各自的赋值条目里。
            赋值条目的名字保留各来源预设原来的控制台名，方便对照。
          </p>
        </div>
      </div>
    </div>

    <!-- AI 解析结果：单独弹窗，不挤占树的版面 -->
    <AiTreeDialog
      :展开="展开解析"
      :解析中="解析中"
      :预设名="解析预设"
      :行="解析行"
      :错误="解析错误"
      @应用="应用解析"
      @关闭="展开解析 = false"
    />
  </div>
</template>
