<script setup lang="ts">
import { computed, ref } from 'vue';
import SplitHandle from './SplitHandle.vue';
import { useWorkspaceStore } from '../core/store.ts';
import type { AiResult } from '../types.ts';

const props = defineProps<{
  /** 当前要对比的 AI 结果；null 表示没有待对比的 */
  对比结果: AiResult | null;
  /** 对比队列里还剩几条（含当前这条） */
  对比剩余: number;
}>();

const emit = defineEmits<{
  /** 把 AI 版本写进目标条目 */
  写入: [];
  /** 带着修改意见让 AI 重做这一条 */
  重新生成: [];
  /** 不用 AI 版本，保留原条目 */
  放弃: [];
  关闭对比: [];
}>();

const store = useWorkspaceStore();

/** 上半区高度占比，拖中间那根线可调 */
const 上半占比 = ref(40);

/*
 * 样式必须用 computed 返回对象，不能在模板里写 `:style="{ flex: `${上半占比} 1 0%` }"`。
 * 模板字符串里的 ref 一旦没被正确解包，生成的就是 "[object Object] 1 0%" 这种非法 CSS，
 * 整条声明被浏览器丢弃，元素退回内容高度 —— 上半区撑满、分隔线掉到最底部。
 */
const 上半样式 = computed(() => ({ flex: `${上半占比.value} 1 0%` }));
const 下半样式 = computed(() => ({ flex: `${100 - 上半占比.value} 1 0%` }));

/** 对比要替换掉的那条原条目 */
const 原条目 = computed(() =>
  props.对比结果
    ? (store.slot.prompts.find(t => t._uid === props.对比结果!.targetUids[0]) ?? null)
    : null,
);

/**
 * 原条目当前的内容。
 * 用 `content`（当前值）而不是 `_origin`（搬进来时的原文）——
 * 用户可能已经手动改过，要对比的是「现在这条」和「AI 建议的那条」。
 */
const 原文 = computed(() => 原条目.value?.content ?? '');
</script>

<template>
  <div class="flex-1 min-h-0 flex flex-col">
    <template v-if="对比结果">
      <div class="px-2.5 py-1.5 shrink-0 flex items-center gap-2 text-xs border-b border-line">
        <i class="fa-solid fa-code-compare text-accent" />
        <span class="font-medium">条目比对</span>
        <span v-if="对比结果.mode === 'merged'" class="text-warn">
          由 {{ 对比结果.targetUids.length }} 条合并
        </span>
        <span class="text-muted ml-auto whitespace-nowrap">剩余 {{ 对比剩余 }} 条</span>
        <button
          class="text-muted hover:text-danger shrink-0"
          title="退出对比，未处理的结果仍保留在 AI 助手列表里"
          @click="emit('关闭对比')"
        >
          <i class="fa-solid fa-xmark" />
        </button>
      </div>

      <!-- 上半：旧条目（当前目标里的） -->
      <div class="min-h-0 flex flex-col" :style="上半样式">
        <div
          class="px-2.5 py-1.5 shrink-0 text-[10px] bg-surface2/45 text-muted border-b border-line/50 flex items-center gap-1.5"
        >
          <i class="fa-solid fa-file-lines" />旧条目（现在目标里的）
          <span class="ml-auto opacity-70 truncate">{{ 原条目?.name ?? '（条目已不存在）' }}</span>
        </div>
        <pre
          class="flex-1 min-h-0 overflow-auto m-2 p-2 rounded-md bg-surface2/50 text-[11px] leading-relaxed whitespace-pre-wrap font-mono"
        >{{ 原文 || '（空条目）' }}</pre>
      </div>

      <SplitHandle @拖动="比例 => (上半占比 = 比例)" />

      <!-- 下半：新条目（AI 生成的） -->
      <div class="min-h-0 flex flex-col" :style="下半样式">
        <div class="px-2.5 py-1.5 shrink-0 text-[10px] bg-surface2/45 border-b border-line/50 flex items-center gap-1.5">
          <i class="fa-solid fa-wand-magic-sparkles text-accent" />
          <span class="text-accent">新条目（AI 生成）</span>
          <span class="text-muted ml-auto truncate">{{ 对比结果.name }}</span>
        </div>
        <pre
          class="flex-1 min-h-0 overflow-auto m-2 p-2 rounded-md bg-surface2/50 text-[11px] leading-relaxed whitespace-pre-wrap font-mono"
        >{{ 对比结果.content || '（空）' }}</pre>
      </div>

      <!-- 三个动作固定在最下方 -->
      <div class="px-2.5 py-2 shrink-0 border-t border-line flex gap-1.5">
        <button
          class="flex-1 px-2 py-1.5 rounded-md bg-accent text-accent-text font-medium text-xs"
          title="把下面这条写进上面对应的目标条目"
          @click="emit('写入')"
        >
          <i class="fa-solid fa-check mr-1" />写入
        </button>
        <button
          class="flex-1 px-2 py-1.5 rounded-md border border-line hover:border-accent text-xs"
          title="写点修改意见，让 AI 重做这一条"
          @click="emit('重新生成')"
        >
          <i class="fa-solid fa-rotate-right mr-1" />重新生成
        </button>
        <button
          class="flex-1 px-2 py-1.5 rounded-md border border-line hover:border-danger hover:text-danger text-xs"
          title="不用 AI 版本，保留原条目"
          @click="emit('放弃')"
        >
          <i class="fa-solid fa-xmark mr-1" />放弃
        </button>
      </div>
    </template>

    <div v-else class="p-4 text-xs text-muted leading-relaxed">
      没有待比对的条目。<br />
      在「AI 助手」里点某条生成结果，或勾选后点「替换选中」，这里就会出现新旧对照。
    </div>
  </div>
</template>
